import assert from 'node:assert/strict';
import {spawn} from 'node:child_process';
import {mkdtemp,readFile,writeFile,mkdir,rm} from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
const out='/tmp/legendgirl-cenas-camadas';
await mkdir(out,{recursive:true});await mkdir('docs/diario-ia/qa-resultados/yuna',{recursive:true});
const profile=await mkdtemp(path.join(os.tmpdir(),'legendgirl-yuna-chrome-'));
const chrome=spawn('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',['--headless=new','--mute-audio','--no-first-run','--no-default-browser-check','--autoplay-policy=no-user-gesture-required','--remote-debugging-port=0','--user-data-dir='+profile,'about:blank'],{stdio:'ignore'});
let ws;
try{
 let port;for(let i=0;i<100;i++){try{port=(await readFile(path.join(profile,'DevToolsActivePort'),'utf8')).split('\n')[0];break;}catch{}await new Promise(r=>setTimeout(r,100));}
 assert.ok(port,'Chrome de QA inicializado');
 const tabs=await(await fetch('http://127.0.0.1:'+port+'/json/list')).json();ws=new WebSocket(tabs.find(t=>t.type==='page').webSocketDebuggerUrl);await new Promise(r=>ws.onopen=r);
 let id=0;const pending=new Map();ws.onmessage=e=>{const d=JSON.parse(e.data);if(d.id){pending.get(d.id)?.(d);pending.delete(d.id);}};
 const call=(method,params={})=>new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}));});
 const evaluate=async expression=>{const r=await call('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true});if(r.result?.exceptionDetails)throw Error(JSON.stringify(r.result.exceptionDetails));return r.result?.result?.value;};
 await call('Emulation.setDeviceMetricsOverride',{width:1280,height:800,deviceScaleFactor:1,mobile:false});
 await call('Page.navigate',{url:'http://127.0.0.1:3000/'});for(let i=0;i<300;i++){if(await evaluate('Boolean(window.game)'))break;await new Promise(r=>setTimeout(r,100));}
 await evaluate(`(async()=>{await game.assetsReady;document.querySelector('#game-difficulty').value='EASY';const select=document.querySelector('#debug-phase-select');select.value='garden';select.dispatchEvent(new Event('change',{bubbles:true}));for(let i=0;i<200&&!game.state.toyRoomInstance?.instance?.garden?.ready;i++)await new Promise(r=>setTimeout(r,50));window.phase=game.state.toyRoomInstance.instance.garden;if(!phase.ready)throw Error(phase.error||'Jardim indisponível');game.setPaused(true);})()`);

 const reports=[];
 for(const [format,width,height]of [['desktop',1280,800],['retrato',390,844],['paisagem',844,390]]){
  await call('Emulation.setDeviceMetricsOverride',{width,height,deviceScaleFactor:1,mobile:format!=='desktop'});await new Promise(r=>setTimeout(r,350));
  await evaluate('window.sceneFrames=[]');
  for(const [stage,age]of [['INTRO',1],['INTRO',7],['INTRO',22],['INTRO',41],['INTRO',47],['COMPLETE',2],['COMPLETE',14],['COMPLETE',30],['COMPLETE',49]]){
   const data=await evaluate(`(()=>{phase.state.stage='${stage}';phase.state.age=${age};const before=JSON.stringify(phase.snapshot());phase.render();if(before!==JSON.stringify(phase.snapshot()))throw Error('Cena alterou domínio');const image=phase.canvas.toDataURL();sceneFrames.push(image);return image;})()`);
   await writeFile(out+'/'+format+'-'+stage+'-'+age+'.png',Buffer.from(data.split(',')[1],'base64'));
   if(age===7||age===30){const shot=await call('Page.captureScreenshot',{format:'png'});await writeFile(out+'/'+format+'-pagina-'+stage+'.png',Buffer.from(shot.result.data,'base64'));}
  }
  const sheet=await evaluate(`(()=>{const c=document.createElement('canvas');c.width=1278;c.height=798;const ctx=c.getContext('2d');return Promise.all(sceneFrames.map(async(src,i)=>{const image=new Image();image.src=src;await image.decode();ctx.drawImage(image,i%3*426,Math.floor(i/3)*266,426,266);})).then(()=>c.toDataURL());})()`);await writeFile(out+'/'+format+'-sequencia.png',Buffer.from(sheet.split(',')[1],'base64'));
  reports.push({formato:format,cenas:9,rendererPuro:true});
 }
 await call('Emulation.setDeviceMetricsOverride',{width:1280,height:800,deviceScaleFactor:1,mobile:false});await new Promise(r=>setTimeout(r,350));
 for(const [stage,age,label]of [['INTRO',5,'convite'],['INTRO',22,'receio'],['COMPLETE',30,'comendo']]){
  const motion=await evaluate(`(async()=>{phase.state.stage='${stage}';phase.state.age=${age};window.motionFrames=[];let next=0;const started=performance.now(),startAge=phase.state.age;game.setPaused(false);await new Promise(resolve=>{const frame=now=>{if(now-started>=next){phase.render();motionFrames.push(phase.canvas.toDataURL());next+=250;}if(now-started>2500){game.setPaused(true);resolve();}else requestAnimationFrame(frame);};requestAnimationFrame(frame);});if(phase.state.age<=startAge||new Set(motionFrames).size<5)throw Error('Cena não animou no host');return{label:'${label}',quadros:motionFrames.length,avancoAtivo:phase.state.age-startAge};})()`);reports.push(motion);
  const frames=await evaluate('motionFrames');for(let i=0;i<frames.length;i++)await writeFile(out+'/'+label+'-'+i+'.png',Buffer.from(frames[i].split(',')[1],'base64'));
 }
 console.log(JSON.stringify(reports));await writeFile('docs/diario-ia/qa-resultados/yuna/cenas-camadas.json',JSON.stringify(reports,null,2));
}finally{ws?.close();chrome.kill();await new Promise(r=>chrome.once('exit',r));await rm(profile,{recursive:true,force:true});}
